'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=c=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:c%100?2:0}).format((c||0)/100);
const duration=m=>`${Math.floor(m/60)?Math.floor(m/60)+' hr ':''}${m%60?m%60+' min':''}`.trim();
const S={me:null,config:null,route:0,settingsTab:'business',bookingView:'list',bookingFilter:'all',search:'',dirty:false,bookings:[],quotes:[],wizard:null};
const paths={camera:'M3 7h4l2-3h6l2 3h4v14H3z M16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',image:'M3 3h18v18H3z M3 16l6-6 6 6 3-3 3 3 M15 7h.01',upload:'M12 16V3 M7 8l5-5 5 5 M4 16v5h16v-5',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16 M8 14h2 M14 14h2 M8 18h2',chat:'M4 4h16v12H9l-5 4z M8 8h8 M8 12h5',people:'M9 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8z M2 21v-2a7 7 0 0 1 14 0v2 M17 5a3 3 0 0 1 0 6 M20 21v-3a5 5 0 0 0-3-5',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8z M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',card:'M3 5h18v14H3z M3 10h18 M7 15h4',help:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20z M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 4 M12 17v.1',arrow:'M4 12h16 M14 6l6 6-6 6',left:'M20 12H4 M10 6l-6 6 6 6',up:'M7 17 17 7 M7 7h10v10',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',check:'m5 12 4 4L19 6',close:'m6 6 12 12 M6 18 18 6',plus:'M12 5v14 M5 12h14',link:'m10 13 4-4 M8 16l-2 2a4 4 0 0 1-5-5l5-5a4 4 0 0 1 5 0 M16 8l2-2a4 4 0 0 1 5 5l-5 5a4 4 0 0 1-5 0',copy:'M8 8h13v13H8z M16 8V3H3v13h5',clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20z M12 6v6l4 2',pin:'M12 22s8-8 8-14A8 8 0 0 0 4 8c0 6 8 14 8 14z M12 11a3 3 0 1 0 0-6 3 3 0 0 0 0 6z',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6z m-5 10 3 3 6-6',mail:'M3 5h18v14H3z m0 0 9 7 9-7',car:'M3 10 6 4h12l3 6v8H3z M3 10h18 M6 18v3 M18 18v3 M6 14h2 M16 14h2',truck:'M2 8h12v10H2z M14 11h5l3 4v3h-8 M5 20a2 2 0 1 0 0-4 2 2 0 0 0 0 4z M18 20a2 2 0 1 0 0-4 2 2 0 0 0 0 4z',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',logout:'M10 3H4v18h6 M10 12h12 m-5-5 5 5-5 5',menu:'M3 6h18 M3 12h18 M3 18h18',dollar:'M12 2v20 M17 6H9a4 4 0 0 0 0 8h6a4 4 0 0 1 0 8H6',edit:'m15 4 5 5 M4 15 15 4a3 3 0 0 1 5 5L9 20l-6 1z',trash:'M3 6h18 M8 6V3h8v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',bell:'M5 17V9a7 7 0 0 1 14 0v8l2 2H3z M10 22h4',file:'M5 2h9l5 5v15H5z M14 2v6h5 M8 12h8 M8 16h8',lock:'M5 10h14v12H5z M8 10V6a4 4 0 0 1 8 0v4 M12 15v3',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8z M12 1v3 M12 20v3 M1 12h3 M20 12h3 M4 4l2 2 M18 18l2 2 M4 20l2-2 M18 6l2-2',refresh:'M20 7V2l-3 3A9 9 0 1 0 3 12 M20 7h-5 M20 7a9 9 0 0 1 1 5'};
function icon(name,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;}
const brand=()=>`<a class="brand" href="/" data-nav><span class="brand-mark">k<span>.</span></span>Kontracts</a>`;
const btn=(text,action,cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const nav=(text,url,cls='btn')=>`<a class="${cls}" href="${e(url)}" data-nav>${text}</a>`;
const empty=(title,text,ic='calendar',extra='')=>`<div class="empty"><span class="badge-icon">${icon(ic)}</span><h3>${e(title)}</h3><p>${e(text)}</p>${extra}</div>`;
const skeleton=()=>`<div class="loading"><div class="skeleton" style="width:42%;height:24px"></div><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></div>`;
function dateLabel(ts,options={}){return new Intl.DateTimeFormat('en-US',{timeZone:S.me?.shop?.settings.timezone||S.wizard?.shop?.settings.timezone||'America/New_York',...options}).format(new Date(ts*1000));}
function inZone(ts,zone,opts={}){return new Intl.DateTimeFormat('en-US',{timeZone:zone,...opts}).format(new Date(ts*1000));}
function todayISO(zone='America/New_York'){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return ['year','month','day'].map(k=>parts.find(p=>p.type===k).value).join('-');}
function addDays(date,n){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);}
function localTimestamp(date,time,zone){const desired=Date.parse(date+'T'+time+':00Z');let guess=desired;for(let i=0;i<3;i++){const p=new Intl.DateTimeFormat('en-GB',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date(guess));const get=k=>p.find(x=>x.type===k).value;const actual=Date.parse(`${get('year')}-${get('month')}-${get('day')}T${get('hour')}:${get('minute')}:${get('second')}Z`);guess+=desired-actual;}return Math.floor(guess/1000);}
function statusBadge(status){const labels={pending_approval:'Awaiting approval',awaiting_signature:'Awaiting signature',signed:'Signed & saved',trial:'Free trial',active:'Active',trialing:'Trial',held:'Awaiting deposit',confirmed:'Confirmed',completed:'Completed',cancelled:'Cancelled',expired:'Expired',payment_review:'Payment review',no_show:'No-show',new:'Needs a quote',offered:'Quote sent',reserved:'Reserved',declined:'Declined',paid:'Paid',unpaid:'Not collected',pending:'Pending',refunded:'Refunded',refund_pending:'Refund pending',refund_failed:'Refund failed',partially_refunded:'Partly refunded'};const cls=['signed','active','confirmed','completed','paid','offered'].includes(status)?'green':['pending_approval','awaiting_signature','held','new','payment_review','refund_pending','pending'].includes(status)?'amber':['refund_failed','no_show'].includes(status)?'red':'';return `<span class="pill ${cls}"><span class="dot"></span>${e(labels[status]||status)}</span>`;}
async function api(path,{method='GET',body,headers={}}={}){const h={'X-Requested-With':'Kontracts',...headers};if(S.me?.csrf)h['X-CSRF-Token']=S.me.csrf;if(body!==undefined&&!(body instanceof FormData)){h['Content-Type']='application/json';body=JSON.stringify(body);}const r=await fetch('/api'+path,{method,body,headers:h,credentials:'same-origin',cache:'no-store'});let data;try{data=await r.json();}catch{throw new Error('The server returned an unexpected response. Please try again.');}if(!r.ok){let detail=data.detail||'Something went wrong.';if(Array.isArray(detail))detail=detail.map(d=>`${d.loc?.slice(1).join(' ')||'Field'}: ${d.msg}`).join('; ');const error=new Error(String(detail));error.status=r.status;throw error;}return data;}
let toastTimer;
function toast(message,error=false){clearTimeout(toastTimer);$('#toast-region').innerHTML=`<div class="toast ${error?'error':''}" role="status">${e(message)}</div>`;toastTimer=setTimeout(()=>$('#toast-region').innerHTML='',6500);}
function formError(form,message){let box=$('.form-error',form);if(!box){box=document.createElement('div');box.className='form-error notice error mt16';box.setAttribute('role','alert');form.prepend(box);}box.textContent=message;box.scrollIntoView({block:'nearest',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
function go(url,replace=false){if(BrandState.busy){toast('Finish saving your branding before leaving.',true);return;}if(S.dirty&&!confirm('You have unsaved changes. Leave this page?'))return;if(!closeModal())return;S.dirty=false;if(replace)history.replaceState({},'',url);else history.pushState({},'',url);window.scrollTo(0,0);render();}
function openModal(title,body){const m=$('#modal');m.innerHTML=`<div class="modal-head"><h2 id="modal-title">${e(title)}</h2><button class="icon-btn" data-action="modal-close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!m.open)m.showModal();}
function closeModal(){if(PhotoState.uploadBusy||PhotoState.busy){toast('Finish the photo operation before closing.',true);return false;}if(PhotoState.pending.length){if(!confirm('Discard the photos that have not been saved?'))return false;clearPhotoPending();}const m=$('#modal');if(m.open)m.close();return true;}
function field(label,name,value='',type='text',extra=''){return `<div class="field"><label for="f-${name}">${e(label)}</label><input id="f-${name}" name="${name}" type="${type}" value="${e(value)}" ${extra}></div>`;}
function heading(title,sub,action=''){return `<div class="page-heading"><div><h1>${e(title)}</h1><p>${e(sub)}</p></div>${action}</div>`;}
function footer(){return `<footer class="site-footer">${brand()}<span>Your work. Beautifully organized.</span><div class="row">${nav('Privacy','/privacy','')}${nav('Terms','/terms','')}<a href="mailto:${e(S.config?.support_email)}">Contact</a></div></footer>`;}
function demoBanner(){return S.me?.shop?.demo?'<div class="demo-banner">Demo workspace. Sample customers and simulated payments only. <a href="/register" data-nav>Create your own workspace</a></div>':'';}
async function render(){const route=++S.route;const app=$('#app');try{if(!S.config)S.config=await api('/config');const path=location.pathname;if(path==='/how-payments-work'){resetBrandDocument();app.innerHTML=paymentsExplainer();return;}if(path.startsWith('/invoice/')){await publicInvoice(path.split('/')[2]);return;}if(!path.startsWith('/book/')&&!path.startsWith('/quote/')&&!path.startsWith('/manage/')&&path!=='/brand-preview'&&!S.config.tenant_slug)resetBrandDocument();if(path==='/brand-preview'){try{S.me=await api('/auth/me');}catch(err){if(err.status===401){go('/login',true);return;}throw err;}await initWizard(S.me.shop.slug,false,true);return;}if(path.startsWith('/app')){try{S.me=await api('/auth/me');}catch(err){if(err.status===401){go('/login',true);return;}throw err;}if(route!==S.route)return;renderShell(path);await renderPage(path);return;}if(path==='/'){if(S.config.tenant_slug){await initWizard(S.config.tenant_slug);return;}app.innerHTML=landing();return;}if(['/login','/register','/forgot-password','/reset-password','/verify-email'].includes(path)){app.innerHTML=authPage(path);return;}if(['/terms','/privacy'].includes(path)){app.innerHTML=legalPage(path);return;}if(path==='/google/complete'){app.innerHTML=await googleCompletePage();return;}if(path==='/checkout'){app.innerHTML=`<main id="main" class="booking-manage">${brand()}<div class="card card-pad mt32"><h1>Activate Kontracts</h1><p class="muted mt16">Your subscription checkout is opening securely with Paddle.</p><div id="checkout-status" class="mt24"></div></div></main>`;await openPaddle();return;}if(path.startsWith('/book/')){await initWizard(decodeURIComponent(path.split('/')[2]));return;}if(path.startsWith('/quote/')){await initQuoteWizard(path.split('/')[2]);return;}if(path.startsWith('/manage/')){await renderManage(path.split('/')[2]);return;}if(path.startsWith('/demo-checkout/')){await renderDemoCheckout(path.split('/')[2]);return;}app.innerHTML=`<main id="main" class="error-box card">${empty('Page not found','The link may have changed.','help',nav('Back to home','/','btn primary'))}</main>`;}catch(err){app.innerHTML=`<main id="main" class="error-box card">${empty('We could not open this page',err.message,'help',btn('Try again','reload','primary'))}</main>`;}}
function renderShell(path){const page=path.split('/')[2]||'overview';const shop=S.me.shop;const days=Math.max(0,Math.ceil((shop.trial_end-Date.now()/1000)/86400));const menu=[['overview','Overview','grid'],['bookings','Bookings','calendar'],['quotes','Quote requests','chat'],['photos','Car photos','camera'],['customers','Customers','people'],['services','Services & prices','dollar'],['invoices','Invoices','file']];const bottom=[['setup','Getting started','check'],['branding','Brand & booking page','spark'],['settings','Settings','settings'],['billing','Subscription','card'],['help','Help & activity','help']];const item=([key,label,ic])=>`<a class="nav-item ${page===key?'active':''}" href="/app/${key==='overview'?'':key}" data-nav ${page===key?'aria-current="page"':''}>${icon(ic)}${label}</a>`;$('#app').innerHTML=`<div class="shell"><button class="mobile-backdrop" data-action="menu" aria-label="Close navigation"></button><aside class="sidebar">${brand()}<div class="workspace row"><span class="avatar">${e(shop.name.slice(0,1))}</span><div class="grow"><div class="name">${e(shop.name)}</div><small>Solo workspace</small></div>${icon('down')}</div><div class="nav-caption">Workspace</div><nav aria-label="Main navigation">${menu.map(item).join('')}<div class="nav-caption">Manage</div>${bottom.map(item).join('')}</nav><div class="sidebar-bottom">${shop.billing_status==='trial'?`<div class="trial-note"><strong>${shop.demo?'Your next chapter starts here':days+' days left in your trial'}</strong><p>${shop.demo?'Explore every corner. No real payments.':'One booking page. A calmer business.'}</p>${nav(shop.demo?'Create a workspace':'View subscription',shop.demo?'/register':'/app/billing','btn small wide')}</div>`:''}<div class="account row"><span class="avatar">${e(S.me.user.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><div class="grow"><strong class="small">${e(S.me.user.name)}</strong><div class="muted" style="font-size:10px">Business owner</div></div><button class="icon-btn" data-action="logout" aria-label="Sign out">${icon('logout')}</button></div></div></aside><div class="app-body">${demoBanner()}<header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="crumb">Workspace<span class="slash">/</span><strong>${e([...menu,...bottom].find(x=>x[0]===page)?.[1]||'New booking')}</strong></div><div class="spacer"></div><span class="pill ${shop.published&&shop.entitled?'green':''}"><span class="dot"></span>${shop.published&&shop.entitled?'Booking page live':shop.published?'Subscription required':'Page not published'}</span>${nav('View booking page '+icon('up'),'/book/'+shop.slug,'btn small mobile-hide')}<a href="/app/help" data-nav class="icon-btn" aria-label="Help and activity">${icon('bell')}</a></header><main id="main" class="main">${skeleton()}</main><nav class="mobile-tabs" aria-label="Quick navigation">${[['Overview','/app','grid'],['Bookings','/app/bookings','calendar'],['Prices','/app/services','dollar'],['Photos','/app/photos','camera']].map(([label,url,ic])=>`<a href="${url}" data-nav class="${path===url?'active':''}">${icon(ic)}<span>${label}</span></a>`).join('')}<button data-action="menu" aria-label="More navigation">${icon('menu')}<span>More</span></button></nav></div></div>`;}
async function renderPage(path=location.pathname){const page=path.split('/')[2]||'overview';if(page==='new-booking'){await initWizard(S.me.shop.slug,true);return;}const main=$('#main');if(!main)return;switch(page){case'overview':main.innerHTML=await dashboardPage();break;case'bookings':{S.bookings=(await api('/bookings')).bookings;main.innerHTML=bookingsPage();break;}case'quotes':S.quotes=(await api('/quotes')).quotes;main.innerHTML=quotesPage();break;case'photos':main.innerHTML=await photosPage();break;case'customers':main.innerHTML=customersPage((await api('/customers')).customers);break;case'services':main.innerHTML=servicesPage();break;case'branding':main.innerHTML=await brandingPage();break;case'invoices':main.innerHTML=await invoiceWorkspace();break;case'settings':main.innerHTML=paymentPreferences()+settingsPage();break;case'billing':main.innerHTML=billingPage();break;case'setup':main.innerHTML=await setupPage();break;case'help':main.innerHTML=helpPage(await api('/operations'));break;default:go('/app',true);}}
function landing(){return minimalLanding();}
function authPage(path){let content='';if(path==='/login')content=`<h1>Welcome back.</h1><p>A clearer day starts here.</p><form data-form="login">${field('Email address','email','','email','required autocomplete="email"')}${field('Password','password','','password','required autocomplete="current-password" maxlength="128"')}<div class="text-right mt8">${nav('Forgot password?','/forgot-password','link-button')}</div><button class="btn primary wide" type="submit">Log in ${icon('arrow')}</button></form><div class="auth-bottom">New here? ${nav('Start your free trial','/register','')}</div><hr><a href="/demo" class="btn wide">Try the safe demo</a>`;else if(path==='/register')content=`<h1>Make room for better days.</h1><p>Create your workspace. No card needed for your 14-day trial.</p><form data-form="register"><input type="hidden" name="plan_id" value="${e('solo')}">${field('Your name','name','','text','required minlength="2" maxlength="80" autocomplete="name"')}${field('Business name','business','','text','required minlength="2" maxlength="80"')}${field('Booking page name','slug','','text','required pattern="[a-z0-9]+(-[a-z0-9]+)*" minlength="3" maxlength="45" placeholder="e.g. northline-auto"')}<div class="field"><label for="reg-zone">Your business timezone</label><select id="reg-zone" name="timezone">${zoneOptions('America/New_York')}</select></div>${field('Email address','email','','email','required autocomplete="email"')}${field('Password','password','','password','required minlength="12" maxlength="128" autocomplete="new-password" placeholder="At least 12 characters"')}<div class="honeypot" aria-hidden="true"><input name="website" tabindex="-1" autocomplete="off"></div><label class="check-row mt24"><input type="checkbox" name="accepted_terms" required><span>I agree to the ${nav('Terms','/terms','link-button')} and ${nav('Privacy Policy','/privacy','link-button')}.</span></label><button class="btn primary wide" type="submit">Create my workspace ${icon('arrow')}</button></form><div class="auth-bottom">Already have an account? ${nav('Log in','/login','')}</div>`;else if(path==='/forgot-password')content=`<h1>Let's get you back in.</h1><p>Enter your email and we'll send a password-reset link.</p><form data-form="forgot">${field('Email address','email','','email','required autocomplete="email"')}<button class="btn primary wide" type="submit">Send reset link ${icon('arrow')}</button></form><div class="auth-bottom">${nav('Back to log in','/login','')}</div>`;else if(path==='/reset-password')content=`<h1>A fresh start.</h1><p>Choose a new password with at least 12 characters.</p><form data-form="reset">${field('New password','password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}<button class="btn primary wide" type="submit">Update password</button></form>`;else content=`<h1>One last check.</h1><p>Confirm your email to publish your business's booking page.</p>${btn('Verify my email '+icon('check'),'verify-email','primary wide')}<div class="auth-bottom">${nav('Back to your workspace','/app','')}</div>`;return `<div class="auth-page"><aside class="auth-brand-panel">${brand()}<div><span class="eyebrow">Detailing, without the detours</span><h1 class="mt24">A clearer schedule.<br>A little peace of mind.</h1><p>A simple home for your bookings, quotes and customers. Built around the way you work.</p></div><small>One operator. One calendar. Your business.</small></aside><main id="main" class="auth-content"><div class="auth-form"><div class="auth-logo-mobile">${brand()}</div>${content}</div></main></div>`;}
function zoneOptions(selected){return (S.config?.timezones||['America/New_York','America/Chicago','America/Denver','America/Los_Angeles','America/Phoenix','America/Anchorage','Pacific/Honolulu']).map(z=>`<option value="${z}" ${selected===z?'selected':''}>${z.replaceAll('_',' ')}</option>`).join('');}
async function dashboardPage(){const d=await api('/dashboard');S.bookings=d.bookings;const shop=S.me.shop;const completed=[['Verify email',S.me.user.verified],['Review your business settings',shop.settings.policy_reviewed],['Choose how you collect payment',shop.settings.payment_method==='in_person'||shop.square_connected||shop.demo],['Publish your booking page',shop.published]];return `${heading('A clearer day ahead.',`Here's what's happening at ${shop.name}.`,nav(icon('plus')+' New booking','/app/new-booking','btn primary'))}${!S.me.user.verified?`<div class="notice amber row wrap"><span>Verify your email before publishing your booking page.</span><span class="spacer"></span>${btn('Resend email','resend-verification','small')}</div>`:''}${d.stats.pending_approvals?`<div class="notice amber mt16">${d.stats.pending_approvals} booking request(s) await your approval. ${nav('Review requests','/app/bookings','link-button')}</div>`:''}${d.stats.payment_reviews?`<div class="notice amber mt16">${d.stats.payment_reviews} payment needs review. No appointment was automatically confirmed. ${nav('Open bookings','/app/bookings','link-button')}</div>`:''}${d.stats.email_failures?`<div class="notice error mt16">Some emails exhausted their retries. ${nav('Check delivery activity','/app/help','link-button')}</div>`:''}<div class="stats">${stat('Scheduled value',money(d.stats.scheduled_value),'Confirmed + completed this month','dollar')}${stat('Deposits received',money(d.stats.deposits_received),'Net deposits on this month’s jobs','card')}${stat('Upcoming bookings',d.stats.upcoming,'Confirmed appointments ahead','calendar')}${stat('Quote requests',d.stats.quote_requests,'Waiting for your review','chat')}</div><div class="dashboard-grid"><section class="card"><div class="card-head"><div class="row"><h2>On the calendar</h2><span class="inline-count">${d.bookings.length}</span></div>${nav('View all '+icon('arrow'),'/app/bookings','link-button')}</div>${bookingTable(d.bookings.slice(0,6),true)}<div class="row between" style="padding:15px 24px;border-top:1px solid var(--line)"><span class="muted" style="font-size:10px">${icon('clock')} All appointments in ${e(shop.settings.timezone.split('/')[1].replaceAll('_',' '))} time</span><span class="small muted">${e(d.month)}</span></div></section><aside class="right-rail"><div class="card card-pad link-card"><span class="badge-icon" style="background:white">${icon('link')}</span><h3 class="mt16">One link. Less back-and-forth.</h3><p class="muted small mt8">Put your booking page wherever your customers find you.</p><div class="preview-link">${e(location.host)}/book/${e(shop.slug)}</div>${btn(icon('copy')+' Copy booking link','copy-booking-link','wide')}</div><div class="card card-pad"><h3 style="font-size:15px">${completed.every(x=>x[1])?'Ready for the road':'Your launch checklist'}</h3><ul class="mini-list">${completed.map(([label,done])=>`<li>${icon(done?'check':'clock')}<span class="${done?'':'muted'}">${label}</span></li>`).join('')}</ul>${!completed.every(x=>x[1])?nav('Finish setup '+icon('arrow'),'/app/settings','link-button mt24'):''}</div></aside></div><p class="muted mt24" style="font-size:10px">Scheduled value is not cash collected or profit. Completed service value this month: ${money(d.stats.completed_value)}.</p>`;}
function stat(label,value,note,ic){return `<div class="card stat"><div class="stat-label">${label}${icon(ic)}</div><div class="stat-value">${e(value)}</div><div class="stat-note">${note}</div></div>`;}
function bookingTable(rows,compact=false){if(!rows.length)return empty('Your next booking starts here','Share your booking link or add a phone booking to get started.','calendar',nav('Add a booking','/app/new-booking','btn small'));return `<div class="table-scroll"><table><thead><tr><th>Customer</th><th>Appointment</th>${compact?'':'<th>Service</th>'}<th>Amount</th><th>Status</th><th class="sr-only">View</th></tr></thead><tbody>${rows.map(b=>`<tr class="clickable" data-action="booking-open" data-id="${e(b.id)}" tabindex="0" role="button" aria-label="View booking for ${e(b.customer_name)}"><td><div class="row"><span class="avatar">${e(b.customer_name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><div><strong>${e(b.customer_name)}</strong><div class="table-sub">${e(b.vehicle_notes||b.snapshot.vehicle)}</div></div></div></td><td><div class="date-chip"><span class="date-box"><small>${dateLabel(b.start_ts,{month:'short'})}</small>${dateLabel(b.start_ts,{day:'numeric'})}</span><div><strong>${dateLabel(b.start_ts,{hour:'numeric',minute:'2-digit'})}</strong><div class="table-sub">${duration(b.snapshot.minutes)}</div></div></div></td>${compact?'':`<td><strong>${e(b.snapshot.service)}</strong><div class="table-sub">${e(b.snapshot.vehicle)}</div></td>`}<td><strong>${money(b.total)}</strong><div class="table-sub">${b.payment_status==='paid'?money(b.deposit)+' deposit':e(b.payment_status.replaceAll('_',' '))}</div></td><td>${statusBadge(b.status)}</td><td>${icon('chevron')}</td></tr>`).join('')}</tbody></table></div>`;}
function bookingsPage(){let rows=S.bookings.filter(b=>(S.bookingFilter==='all'||b.status===S.bookingFilter)&&`${b.customer_name} ${b.email} ${b.vehicle_notes}`.toLowerCase().includes(S.search.toLowerCase()));const week=S.week||todayISO(S.me.shop.settings.timezone);return `${heading('Your bookings. All in one place.','A clear view of the work ahead.',`<div class="row">${nav(icon('download')+' Export','/api/export/bookings.csv','btn')}${nav(icon('plus')+' New booking','/app/new-booking','btn primary')}</div>`)}<section class="card"><div class="filter-bar"><input aria-label="Search bookings" placeholder="Search customer or vehicle..." data-search="bookings" value="${e(S.search)}"><select aria-label="Filter status" data-filter="bookings" style="width:auto"><option value="all">All statuses</option>${['pending_approval','confirmed','held','awaiting_signature','completed','payment_review','cancelled','expired','no_show'].map(x=>`<option value="${x}" ${S.bookingFilter===x?'selected':''}>${x.replaceAll('_',' ')}</option>`).join('')}</select><span class="spacer"></span><div class="segmented">${['list','calendar'].map(v=>`<button class="${S.bookingView===v?'active':''}" data-action="booking-view" data-value="${v}">${icon(v==='list'?'file':'calendar')} ${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div></div><div id="booking-results">${S.bookingView==='list'?bookingTable(rows):`<div class="row between" style="padding:15px 20px">${btn(icon('left'),'week-back','small')}<strong class="small">${e(week)} — ${e(addDays(week,6))}</strong>${btn(icon('arrow'),'week-next','small')}</div><div class="table-scroll"><div class="calendar-grid">${Array.from({length:7},(_,i)=>{const day=addDays(week,i);const list=rows.filter(b=>new Intl.DateTimeFormat('en-CA',{timeZone:S.me.shop.settings.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(b.start_ts*1000))===day);return `<div class="cal-day"><div class="cal-date">${new Intl.DateTimeFormat('en-US',{weekday:'short',timeZone:'UTC'}).format(new Date(day+'T12:00Z'))}<strong>${parseInt(day.slice(-2))}</strong></div>${list.map(b=>`<button class="cal-event" data-action="booking-open" data-id="${e(b.id)}"><small>${dateLabel(b.start_ts,{hour:'numeric',minute:'2-digit'})}</small><strong>${e(b.customer_name)}</strong><small>${e(b.snapshot.service)}</small></button>`).join('')}</div>`;}).join('')}</div></div>`}</div></section><p class="muted small mt16">Times shown in ${e(S.me.shop.settings.timezone)}. Travel buffers reserve additional time after each job.</p>`;}
function bookingModal(id){const b=S.bookings.find(x=>x.id===id);if(!b)return;S.openBooking=b;openModal('Booking details',`<div class="row between"><div class="row"><span class="avatar large">${e(b.customer_name.slice(0,1))}</span><div><h3>${e(b.customer_name)}</h3><p class="muted small">${e(b.vehicle_notes||b.snapshot.vehicle)}</p></div></div>${statusBadge(b.status)}</div>${b.status==='payment_review'?'<div class="notice amber mt24">A deposit was received, but the reservation could not be confirmed. Contact the customer, then reschedule or refund. No time is reserved in this state.</div>':''}<div class="detail-grid"><div><label>Appointment</label><p>${dateLabel(b.start_ts,{weekday:'short',month:'short',day:'numeric'})}<br>${dateLabel(b.start_ts,{hour:'numeric',minute:'2-digit',timeZoneName:'short'})}</p></div><div><label>Service</label><p>${e(b.snapshot.service)}<br><span class="muted">${duration(b.snapshot.minutes)} + ${b.snapshot.buffer_minutes} min buffer</span></p></div><div><label>Contact</label><p><a href="mailto:${e(b.email)}">${e(b.email)}</a><br>${e(b.phone)}</p></div><div><label>Location</label><p>${e(b.address)}</p></div></div>${b.notes?`<div class="quote-note">${e(b.notes)}</div>`:''}<hr><div class="money-lines">${b.snapshot.lines.map(l=>`<div><span>${e(l.name)}</span><span>${money(l.amount)}</span></div>`).join('')}<div><span>Tax</span><span>${money(b.tax)}</span></div><div class="total"><span>Service total</span><span>${money(b.total)}</span></div><div><span>Deposit · ${e(b.payment_status.replaceAll('_',' '))}</span><span>${money(b.deposit)}</span></div>${b.refunded?`<div><span>Refunded</span><span>${money(b.refunded)}</span></div>`:''}</div><div class="modal-actions">${b.status==='pending_approval'?btn('Approve & email customer','approve-job','primary',`data-id="${e(b.id)}"`):''}${b.status==='awaiting_signature'?nav('View invoice','/app/invoices','btn primary'):''}${['confirmed','payment_review'].includes(b.status)?btn(icon('calendar')+' Reschedule','reschedule-open','',`data-id="${e(b.id)}"`):''}${['confirmed','completed'].includes(b.status)&&b.start_ts<Date.now()/1000?btn(icon('check')+' Finish & sign invoice','finish-invoice','primary',`data-id="${e(b.id)}"`):''}${['pending_approval','confirmed','held','payment_review'].includes(b.status)?btn('Cancel booking','booking-action','danger',`data-id="${e(b.id)}" data-value="cancel"`):''}${['paid','refund_pending','refund_failed'].includes(b.payment_status)?btn('Refund deposit','refund-open','',`data-id="${e(b.id)}"`):''}${btn(icon('camera')+' Car photos','photos-open','',`data-id="${e(b.id)}"`)}${btn(icon('copy')+' Customer link','copy-customer-link','',`data-id="${e(b.id)}"`)}</div><p class="small muted mt16">Cancelling an appointment does not automatically issue a refund. Service payments go to the detailer, through Square or in person. Signing does not mark a job paid.</p>`);}
function quotePhotoUrl(id,thumbnail=false){return '/api/photos/'+encodeURIComponent(id)+(thumbnail?'?thumbnail=true':'');}
function quotesPage(){return `${heading('A little review. A better quote.','For the jobs that need a closer look.')}<div class="card">${S.quotes.length?S.quotes.map(q=>`<div class="quote-item"><div class="row"><span class="avatar">${e(q.customer_name.slice(0,1))}</span><div class="grow"><h3 style="font-size:14px">${e(q.customer_name)}</h3><p class="muted small">${e(q.vehicle_notes||q.vehicle)} · ${e(q.zip)} · ${dateLabel(q.created_at,{month:'short',day:'numeric'})}</p></div>${statusBadge(q.status)}</div><p class="quote-note">${e(q.notes||'No additional notes.')}</p>${q.photos.length?`<div class="photo-grid">${q.photos.map(id=>`<div class="quote-photo-tile"><a href="${e(quotePhotoUrl(id))}" target="_blank" rel="noopener"><img src="${e(quotePhotoUrl(id,true))}" alt="Customer-submitted vehicle condition photo" loading="lazy"></a><button class="icon-btn" data-action="quote-photo-delete" data-id="${e(id)}" aria-label="Delete quote photo">${icon('close')}</button></div>`).join('')}</div>`:''}<div class="row wrap mt16"><span class="muted small">${e(q.email)} · ${e(q.phone)}</span><span class="spacer"></span>${['new','offered'].includes(q.status)?`${btn(q.status==='offered'?'Edit quote':'Prepare a quote','quote-offer','primary small',`data-id="${e(q.id)}"`)}${btn('Decline','quote-decline','small',`data-id="${e(q.id)}"`)}`:q.amount?`<strong>${money(q.amount)}</strong>`:''}</div></div>`).join(''):empty('No requests waiting','When a customer describes a heavy-condition job, their quote request will appear here.','chat')}</div>`;}
function customersPage(rows){return `${heading('Familiar faces. All the details.','Customer records are created automatically from your bookings.')}<div class="card">${rows.length?`<div class="table-scroll"><table><thead><tr><th>Customer</th><th>Contact</th><th>Bookings</th><th>Completed service value</th><th>Latest appointment</th></tr></thead><tbody>${rows.map(c=>`<tr><td><div class="row"><span class="avatar">${e(c.name.slice(0,1))}</span><strong>${e(c.name)}</strong></div></td><td><a href="mailto:${e(c.email)}">${e(c.email)}</a><div class="table-sub">${e(c.phone)}</div></td><td>${c.bookings}</td><td>${money(c.completed_value)}</td><td>${dateLabel(c.last_booking,{month:'short',day:'numeric',year:'numeric'})}</td></tr>`).join('')}</tbody></table></div>`:empty('Your customer list starts with a booking','Book a customer and their contact information will be organized here.','people')}</div><p class="muted small mt16">Completed service value is not verified final payment collection. Use booking exports for your own reconciliation.</p>`;}
function servicesPage(){return pricingPage();}
function settingsPage(){const shop=S.me.shop,s=shop.settings,tab=S.settingsTab;let content='';if(tab==='business')content=`<div class="row between wrap"><h2>Make it yours.</h2>${nav('Logo, colors & booking link','/app/branding','btn small')}</div><p class="muted small mt8 mb16">Your customers see these details on your booking page.</p><form data-form="settings-business" data-dirty><div class="form-grid">${field('Business name','name',s.name,'text','required maxlength="80"')}${field('City / area','city',s.city,'text','required maxlength="80"')}<div class="full">${field('Short introduction','tagline',s.tagline,'text','maxlength="180"')}</div>${field('Business phone','phone',s.phone,'tel','maxlength="25"')}${field('Business contact email','contact_email',s.contact_email,'email','required')}<div class="field full"><label for="zip-list">Service-area ZIP codes</label><textarea id="zip-list" name="zip_codes" required placeholder="78701, 78702, 78703">${e(s.zip_codes.join(', '))}</textarea><small>Five-digit US ZIP codes, separated by commas. Customers outside this area cannot book online.</small></div><div class="field full"><label for="business-zone">Business timezone</label><select id="business-zone" name="timezone">${zoneOptions(s.timezone)}</select><small>Appointments are shown in your business timezone, not the visitor's timezone.</small></div><label class="check-row full"><input type="checkbox" name="requires_water" ${s.requires_water?'checked':''}><span>Customers must provide water access</span></label><label class="check-row full"><input type="checkbox" name="requires_power" ${s.requires_power?'checked':''}><span>Customers must provide power access</span></label></div><div class="form-footer"><button class="btn primary" type="submit">Save business details ${icon('check')}</button></div></form>`;if(tab==='schedule')content=`<h2>A schedule that fits your day.</h2><p class="muted small mt8 mb16">Working hours include the service and its travel buffer. ${e(s.timezone)}.</p><form data-form="settings-schedule" data-dirty>${s.hours.map((h,i)=>`<div class="hours-row"><label class="check-row"><input type="checkbox" name="day-${i}" ${h.enabled?'checked':''}><span>${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][i]}</span></label><input aria-label="${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][i]} opening time" type="time" name="start-${i}" value="${h.start}" required><span class="muted">—</span><input aria-label="${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][i]} closing time" type="time" name="end-${i}" value="${h.end}" required></div>`).join('')}<hr><div class="form-grid">${field('Travel buffer (minutes)','buffer_minutes',s.buffer_minutes,'number','required min="0" max="180"')}${field('Minimum booking notice (hours)','lead_hours',s.lead_hours,'number','required min="1" max="168"')}${field('Book up to this many days ahead','horizon_days',s.horizon_days,'number','required min="7" max="90"')}</div><div class="form-footer"><button class="btn primary" type="submit">Save availability ${icon('check')}</button></div></form><hr><div class="row between"><div><h3>Time off & blocked hours</h3><p class="muted small mt8">Block personal appointments or jobs booked elsewhere.</p></div>${btn(icon('plus')+' Block time','block-open','small')}</div><div id="blocks-list" class="mt16">${btn('View blocked time','blocks-load','small')}</div>`;if(tab==='payments')content=`<h2>Keep the money where it belongs.</h2><p class="muted small mt8 mb16">Your customers' deposits go to your own Square seller account.</p><div class="integration"><span class="integration-logo">□</span><div class="grow"><h3>Square</h3><p>${shop.square_connected?'Connected to your US seller account.':shop.demo?'Demo mode: payments are simulated.':'Connect one active US location to accept deposits.'}</p></div>${shop.square_connected?`<span class="pill green">Connected</span>`:btn('Connect Square','square-connect','primary small')}</div>${!shop.square_configured&&!shop.demo?'<div class="notice amber mt16">The platform operator must configure Square credentials and the webhook endpoint before this connection can be activated.</div>':''}<form data-form="settings-payments" data-dirty><div class="form-grid mt24">${field('Deposit percentage','deposit_percent',s.deposit_percent,'number','required min="0" max="100"')}${field('Service tax rate (%)','tax_rate',(s.tax_basis_points/100).toFixed(2),'number','required min="0" max="20" step="0.01"')}</div><p class="muted small mt16">A 0% deposit confirms bookings without collecting payment. Tax is a business-configured rate, not an automatic US tax determination. Confirm applicability with your adviser.</p><div class="form-footer"><button class="btn primary" type="submit">Save payment rules ${icon('check')}</button></div></form>${shop.square_connected?`<hr>${btn('Disconnect Square','square-disconnect','danger small')}<p class="muted small mt8">Your page is unpublished when disconnected. Unresolved deposits must be handled first.</p>`:''}`;if(tab==='policy')content=`<h2>Set expectations, clearly.</h2><p class="muted small mt8 mb16">Customers accept your policy before booking. Review the sample text for your business.</p><form data-form="settings-policy" data-dirty>${field('Self-service changes close before a job (hours)','cancellation_hours',s.cancellation_hours,'number','required min="0" max="168"')}<div class="field mt16"><label for="policy">Cancellation & rescheduling policy</label><textarea id="policy" name="cancellation_policy" required minlength="20" maxlength="2000" style="min-height:170px">${e(s.cancellation_policy)}</textarea></div><label class="check-row mt24"><input type="checkbox" name="policy_reviewed" ${s.policy_reviewed?'checked':''}><span>I have checked my service prices, ZIP codes, tax rate, availability and cancellation policy for this business. I understand refunds are separate from cancellations.</span></label><div class="form-footer"><button class="btn primary" type="submit">Save policy ${icon('check')}</button></div></form><hr><div class="row between wrap"><div><h3>Your booking page</h3><p class="muted small mt8">${shop.published?'Live and accepting bookings.':'Not visible to customers until you publish.'}</p></div>${btn(shop.published?'Unpublish page':'Publish booking page','publish',shop.published?'':'primary',`data-value="${!shop.published}"`)}</div>`;if(tab==='account')content=`<h2>Your account & data.</h2><p class="muted small mt8 mb16">${e(S.me.user.email)}</p><form data-form="change-password">${field('Current password','current_password','','password','required autocomplete="current-password"')}${field('New password','password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}<div class="form-footer"><button class="btn primary" type="submit">Change password</button></div></form><hr><h3>Take your data with you</h3><p class="muted small mt8">Exports include your business records, without passwords or payment-provider credentials.</p><div class="row wrap mt16"><a class="btn" href="/api/export/bookings.csv">${icon('download')} Bookings CSV</a><a class="btn" href="/api/export/account.json">${icon('download')} Account JSON</a></div><hr><h3>Delete your account</h3><p class="muted small mt8">Resolve upcoming jobs and pending payments, and cancel any active subscription first. Deletion cannot be undone.</p>${btn('Delete account','delete-account-open','danger small mt16')}`;return `${heading('A setup that feels like you.','A few good defaults. Full control where it matters.')}<div class="settings-layout"><nav class="settings-nav" aria-label="Settings sections">${[['business','Business profile'],['schedule','Availability'],['payments','Payments'],['policy','Policy & publishing'],['account','Account & data']].map(([key,label])=>`<button class="${tab===key?'active':''}" data-action="settings-tab" data-value="${key}">${label}</button>`).join('')}</nav><section class="card card-pad">${content}</section></div>`;}
function billingPage(){return minimalBilling();}
function helpPage(data){return `${heading('A little help, right here.','Answers, delivery status and your latest account activity.')}<div class="card card-pad"><h2>Questions? Start here.</h2><div class="faq"><details><summary>Why isn't my booking page live?</summary><p>Verify your email, review your policy and business settings, connect Square or intentionally set deposits to zero, then publish under Settings → Policy & publishing. Your trial or subscription must be active.</p></details><details><summary>Does cancelling a booking return the deposit?</summary><p>No. Cancelling releases the appointment. Refunds are a separate, explicit action under Booking details. Review your policy and customer agreement before refunding.</p></details><details><summary>What does “Payment review” mean?</summary><p>A payment was verified after its reservation was unavailable. No appointment was automatically confirmed. Contact the customer and either choose an available time or refund the deposit.</p></details><details><summary>How are other calendars handled?</summary><p>This release uses the Kontracts calendar as its scheduling record. Add phone bookings and block other commitments here. External calendar sync, multiple operators and route optimization are not included.</p></details><details><summary>Why haven't emails arrived locally?</summary><p>In development without SMTP, messages are saved as .eml files in data/mail instead of being sent. Production requires configured SMTP. The queue below shows messages waiting or retrying.</p></details></div><p class="muted small mt24">Support: <a class="link-button" href="mailto:${e(S.config.support_email)}">${e(S.config.support_email)}</a></p></div><div class="card mt24"><div class="card-head"><h2>Email delivery queue</h2>${btn(icon('refresh')+' Retry failed messages','retry-emails','small')}</div>${data.email_queue.length?`<div class="table-scroll"><table><thead><tr><th>Subject</th><th>Attempts</th><th>Last issue</th></tr></thead><tbody>${data.email_queue.map(m=>`<tr><td>${e(m.subject)}</td><td>${m.attempts} / 8</td><td>${e(m.last_error||'Queued')}</td></tr>`).join('')}</tbody></table></div>`:empty('All caught up','No messages are currently waiting in your delivery queue.','mail')}</div><div class="card mt24"><div class="card-head"><h2>Recent activity</h2></div>${data.activity.length?`<div class="table-scroll"><table><thead><tr><th>Action</th><th>When</th></tr></thead><tbody>${data.activity.map(a=>`<tr><td>${e(a.action.replaceAll('.',' · ').replaceAll('_',' '))}</td><td>${dateLabel(a.created_at,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}</td></tr>`).join('')}</tbody></table></div>`:empty('A clean slate','Important booking and account changes appear here.','file')}</div>`;}
function legalPage(path){const privacy=path==='/privacy';const reviewed=privacy?S.config.privacy_text:S.config.terms_text;if(reviewed)return `<div class="marketing"><nav class="site-nav">${brand()}${nav('Back to home','/','btn small')}</nav><main id="main" class="legal"><h1>${privacy?'Privacy policy':'Terms of service'}</h1><div class="policy-text">${e(reviewed)}</div></main></div>`;return `<div class="marketing"><nav class="site-nav">${brand()}${nav('Back to home','/','btn small')}</nav><main id="main" class="legal"><h1>${privacy?'Privacy policy':'Terms of service'}</h1>${!S.config.legal_name?'<div class="notice amber">Pre-launch document. The operator must add its legal identity and review these terms before production use.</div>':''}<p>Service operator: ${e(S.config.legal_name||'Operator details pending')}. ${e(S.config.legal_address||'')} Contact: ${e(S.config.support_email)}.</p>${privacy?`<h2>What the service processes</h2><p>Kontracts stores business-account details, authentication records, service settings, booking information, customer contact details, optional vehicle photographs, quote requests and operational logs. Do not upload payment-card information or unrelated sensitive documents.</p><h2>Why information is used</h2><p>Information is used to operate accounts, calculate quotes, schedule work, communicate service updates, reconcile payments, provide support and protect the service. This application does not include advertising trackers or sell personal data.</p><h2>Payments and service providers</h2><p>Square handles detailing deposits on the business's own seller account. Paddle handles the software subscription. Card details are entered on provider-hosted checkouts and are not stored by Kontracts. Hosting, email and payment providers process information needed for their services.</p><h2>Business and customer responsibilities</h2><p>The detailing business determines why it collects customer information and is responsible for its customer notices and lawful use. The platform processes booking information to deliver the software. Contact the detailing business about service bookings and the platform operator about software-account data.</p><h2>Access, deletion and retention</h2><p>Business owners can export account and booking records. Account deletion removes active application records after outstanding operational obligations are resolved. Independent payment-provider records may remain under their own retention requirements. The operator must publish its actual backup retention period and data-processing terms before launch. Customer requests can be made through the business or the operator's contact address.</p><h2>Security and international processing</h2><p>The service uses encrypted connections when deployed over HTTPS, server-side access controls, password hashing and encrypted payment connection credentials. No service can promise absolute security. The platform is intended to be operated from India for US businesses; hosting and vendors may process information in other locations identified by the operator.</p><h2>Essential cookies</h2><p>An essential, HTTP-only session cookie keeps business owners signed in. The production app does not store passwords or payment-provider secrets in browser storage.</p>`:`<h2>The software</h2><p>Kontracts is software for a single-operator detailing business to present services, accept booking requests, schedule work and manage deposits. It is not the provider of detailing services and does not guarantee customer acquisition, income, uninterrupted availability or a particular commercial result.</p><h2>Your business</h2><p>You are responsible for accurate prices, service-area settings, tax treatment, availability, cancellation terms, customer communications, fulfilment, and compliance applicable to your detailing operation. Keep off-platform commitments recorded in the calendar.</p><h2>Subscriptions</h2><p>The current monthly plans are Starter USD 49, Pro USD 69 and Business USD 99, plus applicable taxes. A 14-day internal trial requires no card and does not start a paid subscription automatically. Subscription charges, receipts, renewal and cancellation are managed through Paddle. Review the actual checkout terms before purchasing. Cancellation takes effect as specified in the billing portal.</p><h2>Customer deposits</h2><p>Service deposits are processed through the detailing business's Square account. Processor fees and provider terms apply separately. Cancelling an appointment does not automatically refund a deposit. The business must review and handle refunds, disputes and service-related complaints.</p><h2>Availability and changes</h2><p>Appointment availability is checked when a reservation is created. A temporary reservation may expire before payment. Late or conflicting payments require business review rather than automatic confirmation. Emails and third-party payment services can fail or be delayed; monitor the dashboard.</p><h2>Acceptable use</h2><p>Do not misuse customer data, upload unlawful material, attempt to access another business's records, interfere with the service, evade payment, or send unsolicited communications through the service. Accounts may be suspended for abuse, security risks or unpaid subscriptions.</p><h2>Account closure and data</h2><p>Business owners may export records and request deletion. Resolve upcoming bookings, pending payments and active subscriptions before account closure. Provider records and backups are subject to their separate retention arrangements.</p><h2>Operator review required</h2><p>These pre-launch terms do not establish a finalized jurisdiction, liability allocation, dispute mechanism or service-level agreement. The operator must obtain appropriate review and publish completed terms, legal identity, refund policy and data-processing information before taking live subscriptions.</p>`}</main>${footer()}</div>`;}
function selection(){const w=S.wizard;return {package_id:w.package_id,vehicle_id:w.vehicle_id,extra_ids:w.extra_ids,zip:w.zip,condition:w.condition,quote_token:w.quote_token||null};}
function wizardBase(){return (S.wizard.manual||S.wizard.preview)?'/preview':'/public/shops/'+S.wizard.shop.slug;}
async function initWizard(slug,manual=false,preview=false){const shop=await api(preview?'/branding/preview':manual?'/preview-shop':'/public/shops/'+encodeURIComponent(slug));S.wizard={shop,manual,preview,step:1,package_id:shop.settings.packages[0]?.id||'',vehicle_id:shop.settings.vehicles[0]?.id||'',extra_ids:[],zip:'',condition:'standard',date:todayISO(shop.settings.timezone),start_ts:null,price:null,priceError:'',slots:[],customer:{},idempotency_key:crypto.randomUUID(),photos:[],version:0};renderWizard();}
async function initQuoteWizard(raw){const result=await api('/public/quotes/'+encodeURIComponent(raw));const q=result.quote;S.wizard={shop:result.shop,manual:false,step:2,package_id:'custom',vehicle_id:q.vehicle_id,extra_ids:[],zip:q.zip,condition:'standard',quote_token:raw,date:todayISO(result.shop.settings.timezone),start_ts:null,price:null,priceError:'',slots:[],customer:q,idempotency_key:crypto.randomUUID(),photos:[],version:0,offer:q};await priceWizard();renderWizard();await loadSlots();}
function renderWizard(){const w=S.wizard,s=w.shop.settings;const title=w.manual?'Add a phone booking':w.quote_token?'Your custom quote is ready.':(w.shop.branding?.headline||'A fresh start for your car.');const steps=w.condition==='heavy'?['Your detail','Your details']:['Your detail','Pick a time','Your details'];const effective=w.condition==='heavy'&&w.step===3?2:w.step;const businessMark=w.shop.name[0];const layout=`${w.shop.demo?'<div class="demo-flag">You are exploring a sample business. All bookings and payments here are demonstrations.</div>':''}${w.manual?'<div class="notice amber mb16">Manual request: review and approve this job after saving it. Approval triggers the customer email and any applicable Square deposit link.</div>':''}<div class="booking-intro"><h1>${e(title)}</h1><p>${w.manual?'Record the details, then approve the requested time.':e(w.shop.branding?.introduction||s.tagline)}</p></div><div class="steps">${steps.map((label,i)=>`${i?'<span class="step-line"></span>':''}<div class="step ${effective===i+1?'active':effective>i+1?'done':''}"><span>${effective>i+1?'✓':i+1}</span>${label}</div>`).join('')}</div><div class="booking-layout"><section id="wizard-content">${wizardStep()}</section><aside id="wizard-summary" class="summary">${wizardSummary()}</aside></div>`;if(w.manual){$('#main').innerHTML=layout;return;}applyBrandDocument(w.shop);$('#app').innerHTML=`<div class="booking-page" style="${brandStyle(w.shop)}">${w.preview?'<div class="brand-preview-banner"><span><strong>Draft preview.</strong> No real bookings or payments. Changes are not live until published.</span><button class="btn small" data-action="brand-return">Back to editor</button></div>':''}${businessHeader(w.shop)}${businessCover(w.shop)}<main id="main" class="booking-main">${layout}</main>${businessFooter(w.shop)}</div>`;}
function wizardStep(){const w=S.wizard,s=w.shop.settings;if(w.step===1)return `<div class="booking-section"><h2>First, where are we heading?</h2><div class="field"><label for="booking-zip">Your five-digit ZIP code</label><input id="booking-zip" data-wfield="zip" inputmode="numeric" maxlength="5" pattern="[0-9]{5}" value="${e(w.zip)}" placeholder="e.g. ${e(s.zip_codes[0])}" autocomplete="postal-code"><small>US addresses only. We validate the ZIP and your detailer's service area.</small></div></div><div class="booking-section"><h2>Choose your service</h2>${s.packages.map(p=>`<button class="option-card ${w.package_id===p.id?'selected':''}" data-action="wizard-package" data-value="${e(p.id)}" aria-pressed="${w.package_id===p.id}"><span class="radio"></span><div class="grow"><h3>${e(p.name)}</h3><p>${e(p.description)}<br>${duration(resolvedRate(p,s.vehicles.find(v=>v.id===w.vehicle_id)||s.vehicles[0]).minutes)} before extras</p></div><span class="amount">${money(resolvedRate(p,s.vehicles.find(v=>v.id===w.vehicle_id)||s.vehicles[0]).price)}</span></button>`).join('')}</div><div class="booking-section"><h2>What are you driving?</h2><div class="vehicle-grid">${s.vehicles.map((v,i)=>`<button class="vehicle-option ${w.vehicle_id===v.id?'selected':''}" data-action="wizard-vehicle" data-value="${e(v.id)}" aria-pressed="${w.vehicle_id===v.id}">${icon(i===2?'truck':'car')}<strong>${e(v.name)}</strong><span>${money(resolvedRate(s.packages.find(p=>p.id===w.package_id)||s.packages[0],v).price)} service</span></button>`).join('')}</div></div>${s.extras.length?`<div class="booking-section"><h2>Anything extra?</h2>${s.extras.map(x=>`<label class="extra-item"><input type="checkbox" data-wextra="${e(x.id)}" ${w.extra_ids.includes(x.id)?'checked':''}><span class="grow">${e(x.name)}<br><small>+ ${x.minutes} min</small></span><strong>+${money(x.price)}</strong></label>`).join('')}</div>`:''}<div class="booking-section"><h2>A quick condition check</h2><label class="check-row"><input type="checkbox" data-wcondition ${w.condition==='heavy'?'checked':''}><span>My vehicle needs special attention: heavy soiling, severe staining or excessive pet hair.<small style="display:block;margin-top:5px;color:var(--muted)">We'll ask for details and photos so the business can quote accurately.</small></span></label></div><div id="wizard-error">${w.priceError?`<div class="notice error">${e(w.priceError)}</div>`:''}</div><div class="booking-buttons"><span class="muted small">Clear pricing. No surprises.</span>${btn(w.condition==='heavy'?'Request a reviewed quote '+icon('arrow'):'Choose a time '+icon('arrow'),'wizard-next','primary',!w.price&&w.condition!=='heavy'?'disabled':'')}</div>`;if(w.step===2)return `${w.offer?`<div class="notice mb16">${e(w.offer.message)}<br><strong>${money(w.offer.amount)} subtotal · ${duration(w.offer.minutes)}</strong></div>`:''}<div class="booking-section"><h2>Find a time that works.</h2><p class="muted small">Appointments are shown in ${e(s.timezone.replaceAll('_',' '))}, regardless of your current location.</p><div class="field mt24"><label for="booking-date">Appointment date</label><input id="booking-date" type="date" data-wdate value="${w.date}" min="${todayISO(s.timezone)}" max="${addDays(todayISO(s.timezone),s.horizon_days)}"></div><div class="date-pills">${Array.from({length:8},(_,i)=>{const day=addDays(todayISO(s.timezone),i);return `<button class="date-pill ${day===w.date?'selected':''}" data-action="wizard-date" data-value="${day}"><span>${new Intl.DateTimeFormat('en-US',{weekday:'short',timeZone:'UTC'}).format(new Date(day+'T12:00Z'))}</span><strong>${parseInt(day.slice(-2))}</strong></button>`;}).join('')}</div><div id="slot-options">${slotMarkup()}</div></div><div class="notice mt24">${icon('clock')} ${w.price?duration(w.price.minutes):''} of service, with time reserved afterward for the detailer's travel buffer.</div><div class="booking-buttons">${w.quote_token?'<span></span>':btn(icon('left')+' Back','wizard-back')}${btn('Your details '+icon('arrow'),'wizard-next','primary',w.start_ts?'':'disabled')}</div>`;const c=w.customer;return `<form data-form="wizard-details"><h2 style="font-size:18px;margin-bottom:22px">${w.condition==='heavy'?'Tell us a little more.':'A few details, and you’re set.'}</h2><div class="form-grid">${field('Full name','customer_name',c.customer_name||'','text','required minlength="2" maxlength="80" autocomplete="name"')}${field('Email address','email',c.email||'','email',`required autocomplete="email" ${w.quote_token?'readonly':''}`)}${field('State (two-letter code)','state',c.state||'','text','required minlength="2" maxlength="2" pattern="[A-Za-z]{2}" autocomplete="address-level1" placeholder="TX"')}${field('Country','country','United States','text','readonly')}${field('Phone number','phone',c.phone||'','tel','required minlength="10" maxlength="25" autocomplete="tel"')}${field('Vehicle year, make & model','vehicle_notes',c.vehicle_notes||'','text','maxlength="160" placeholder="e.g. 2022 Toyota RAV4"')}<div class="full">${field('Service address','address',c.address||'','text','required minlength="8" maxlength="220" autocomplete="street-address" placeholder="Street, city and state"')}</div><div class="field full"><label for="customer-notes">Anything else we should know?</label><textarea id="customer-notes" name="notes" maxlength="1500" placeholder="Parking instructions, condition details, or a question...">${e(c.notes||'')}</textarea></div>${w.condition==='heavy'?'<div class="full">'+photoPicker('quote')+'</div>':'<p class="full muted small">You can add car photos from your private booking link after your appointment is confirmed.</p>'}${s.requires_water?`<label class="check-row full"><input name="has_water" type="checkbox" ${c.has_water?'checked':''} required><span>I can provide access to water at the service location.</span></label>`:''}${s.requires_power?`<label class="check-row full"><input name="has_power" type="checkbox" ${c.has_power?'checked':''} required><span>I can provide access to a power outlet.</span></label>`:''}</div><div class="honeypot" aria-hidden="true"><input name="website" tabindex="-1" autocomplete="off"></div><div class="notice mt24" style="background:#f5f7f1;color:#76826e">${e(s.cancellation_policy)}</div><label class="check-row mt16"><input type="checkbox" name="accepted_policy" required><span>I agree to this business's cancellation policy and confirm the booking details are accurate.</span></label><div class="booking-buttons">${btn(icon('left')+' Back','wizard-back')}<button class="btn primary" type="submit">${w.condition==='heavy'?'Send quote request':'Send booking request'} ${icon('arrow')}</button></div><p class="muted small mt16">${w.condition==='heavy'?'No time is reserved and no payment is taken for a quote request.':'This is a request, not a confirmed appointment. The detailer must approve it before any confirmation or payment link is sent. No payment is taken now.'}</p></form>`;}
function wizardSummary(){const w=S.wizard,p=w.price,s=w.shop.settings;const pkg=s.packages.find(x=>x.id===w.package_id),v=s.vehicles.find(x=>x.id===w.vehicle_id);return `<h2>Your detail</h2><div class="summary-detail"><strong>${e(w.quote_token?'Custom detail':pkg?.name||'Choose a service')}</strong><br><small>${e(v?.name||'')} ${w.zip?'· '+e(w.zip):''}</small>${w.start_ts?`<div class="row mt16">${icon('calendar')}<div>${inZone(w.start_ts,s.timezone,{month:'short',day:'numeric'})}<br><small>${inZone(w.start_ts,s.timezone,{hour:'numeric',minute:'2-digit',timeZoneName:'short'})}</small></div></div>`:''}</div>${w.condition==='heavy'?'<p class="muted small">A reviewed quote is needed. The business will confirm price and duration before you choose an appointment.</p>':p?`<div class="money-lines">${p.lines.map(l=>`<div><span>${e(l.name)}</span><span>${money(l.amount)}</span></div>`).join('')}<div><span>Tax</span><span>${money(p.tax)}</span></div><div class="total"><span>Total</span><span>${money(p.total)}</span></div></div><div class="deposit-box"><span>${s.payment_method==='in_person'?'Online payment':'Deposit after approval'}</span><strong>${s.payment_method==='in_person'?'None':money(p.deposit)}</strong></div><p class="summary-note">${s.payment_method==='in_person'?'Pay the detailer in person. Your request must be approved first.':'No payment is taken when requesting. After approval, the detailer sends a Square link for any deposit.'}</p>`:`<p class="muted small">Enter your ZIP code to check availability and see your complete price.</p>`}<hr><div class="row" style="align-items:flex-start;color:#8c9884;font-size:10px">${icon('shield')}<p>${w.shop.demo?'Demo experience. No real money moves.':'Prices set by the detailer. Kontracts takes no booking commission.'}</p></div>`;}
async function priceWizard(){const w=S.wizard;if(!w)return;const generation=++w.version;w.priceError='';if(w.zip.length!==5){w.price=null;updateWizardPrice();return;}if(w.condition==='heavy'){w.price=null;w.priceError=w.shop.settings.zip_codes.includes(w.zip)?'':'That ZIP code is outside this business’s service area.';updateWizardPrice();return;}try{const result=await api(wizardBase()+'/price',{method:'POST',body:selection()});if(generation!==w.version)return;w.price=result;}catch(err){if(generation!==w.version)return;w.price=null;w.priceError=err.message;}updateWizardPrice();}
function updateWizardPrice(){const w=S.wizard;if(!w)return;const summary=$('#wizard-summary');if(summary)summary.innerHTML=wizardSummary();const error=$('#wizard-error');if(error)error.innerHTML=w.priceError?`<div class="notice error">${e(w.priceError)}</div>`:'';const next=$('[data-action="wizard-next"]');if(next&&w.step===1)next.disabled=w.condition==='heavy'?w.zip.length!==5||Boolean(w.priceError):!w.price;}
function slotMarkup(){const w=S.wizard;if(w.slotsLoading)return skeleton();if(w.slotsError)return `<div class="notice error">${e(w.slotsError)}</div>`;return w.slots.length?`<div class="slots">${w.slots.map(x=>`<button class="slot ${x.start_ts===w.start_ts?'selected':''}" data-action="wizard-slot" data-value="${x.start_ts}" aria-pressed="${x.start_ts===w.start_ts}">${e(x.label)}</button>`).join('')}</div>`:empty('A different day, perhaps?','No available times fit this service on the selected date. Try another day.','calendar');}
async function loadSlots(){const w=S.wizard;w.slotsLoading=true;w.slotsError='';const selected=w.date;const node=$('#slot-options');if(node)node.innerHTML=slotMarkup();try{const result=await api(wizardBase()+'/slots',{method:'POST',body:{...selection(),date:selected}});if(selected!==w.date)return;w.slots=result.slots;}catch(err){w.slots=[];w.slotsError=err.message;}finally{if(selected===w.date){w.slotsLoading=false;const n=$('#slot-options');if(n)n.innerHTML=slotMarkup();}}}
async function submitWizard(form){const w=S.wizard;if(w.preview)throw new Error('This is a draft preview. No booking or payment can be created here. Publish and open your live page to book.');const fd=new FormData(form);const customer={country:'US',state:fd.get('state')||'',customer_name:fd.get('customer_name'),email:fd.get('email'),phone:fd.get('phone'),address:fd.get('address'),vehicle_notes:fd.get('vehicle_notes'),notes:fd.get('notes'),has_water:fd.has('has_water'),has_power:fd.has('has_power')};w.customer=customer;if(w.condition==='heavy'){const data={...selection(),...customer,website:fd.get('website')||''};delete data.has_water;delete data.has_power;const request=new FormData();request.append('data',JSON.stringify(data));if(PhotoState.busy)throw new Error('Wait for your photos to finish optimizing.');const photos=w.photos||[];if(photos.length>3)throw new Error('Choose no more than three photos.');for(const f of photos)request.append('photos',f.file);const result=await api('/public/shops/'+w.shop.slug+'/quote-requests',{method:'POST',body:request});for(const p of w.photos)URL.revokeObjectURL(p.src);w.photos=[];$('#wizard-content').innerHTML=`<div class="card">${empty('Your request is on its way.',result.message,'check')}</div>`;return;}if(!w.submission)w.submission={...selection(),...customer,start_ts:w.start_ts,idempotency_key:w.idempotency_key,accepted_policy:true,website:fd.get('website')||''};const result=await api(w.manual?'/bookings':'/public/shops/'+w.shop.slug+'/book',{method:'POST',body:w.submission});if(w.manual){toast('Request saved. Open the job to approve it and notify the customer.');go('/app/bookings');}else if(result.checkout_url&&result.status==='held'){if(result.checkout_url.startsWith('/'))go(result.checkout_url);else window.location.assign(result.checkout_url);}else go(result.manage_url);}
async function renderManage(raw){const data=await api('/public/manage/'+encodeURIComponent(raw));S.manage={...data,token:raw};const b=data.booking,s=data.shop.settings;const title={pending_approval:'Your request is with the detailer.',awaiting_signature:'Your invoice is ready to sign.',confirmed:'You’re on the calendar.',completed:'All fresh. All finished.',held:'One last step: your deposit.',expired:'This reservation has expired.',cancelled:'Your booking is cancelled.',payment_review:'Payment received. Review needed.',no_show:'This appointment was marked no-show.'}[b.status]||'Your booking';const message={pending_approval:'No appointment is confirmed and no payment has been taken. The detailer will review your request and email you after approval. Requests expire after 48 hours or the requested start time.',awaiting_signature:'The detailer has signed your invoice. Check your email for the private invoice link, review the PDF and sign it to finish this job.',confirmed:'Your appointment is confirmed. We’ll send your details by email.',held:'Your selected time is temporarily reserved. Complete the deposit before the reservation expires.',expired:'No appointment is confirmed. Please contact the business or start a new booking.',cancelled:'Your appointment has been released. Refunds are reviewed separately by the business.',payment_review:'Your payment was received after the time was unavailable. No appointment is confirmed. Contact the business to reschedule or arrange a refund.',completed:'Thanks for choosing '+data.shop.name+'.'}[b.status]||'Contact the business with any questions.';applyBrandDocument(data.shop);$('#app').innerHTML=`<div class="booking-page" style="${brandStyle(data.shop)}">${businessHeader(data.shop,'Your booking')}<main id="main" class="booking-manage"><div class="success-head"><span class="badge-icon">${icon(b.status==='confirmed'||b.status==='completed'?'check':b.status==='held'?'card':'help')}</span><h1>${title}</h1><p>${e(message)}</p></div>${b.status==='held'?`<div class="notice amber mb16">Reservation expires at ${inZone(b.hold_until,s.timezone,{hour:'numeric',minute:'2-digit',timeZoneName:'short'})}. A checkout return alone does not confirm payment.</div>`:''}<div class="card card-pad"><div class="row between"><h3>${e(b.snapshot.service)}</h3>${statusBadge(b.status)}</div><div class="detail-grid"><div><label>When</label><p>${inZone(b.start_ts,s.timezone,{weekday:'long',month:'short',day:'numeric'})}<br>${inZone(b.start_ts,s.timezone,{hour:'numeric',minute:'2-digit',timeZoneName:'short'})}</p></div><div><label>How long</label><p>${duration(b.snapshot.minutes)}</p></div><div><label>Vehicle</label><p>${e(b.vehicle_notes||b.snapshot.vehicle)}</p></div><div><label>Where</label><p>${e(b.address)}</p></div></div><p class="muted small mt16">${b.payment_method==='square'?'Payments go to your detailer through Square.':'Pay your detailer in person. No online payment link is needed.'}</p><hr><div class="money-lines"><div><span>Service total</span><strong>${money(b.total)}</strong></div><div><span>Deposit</span><span>${money(b.deposit)} · ${e(b.payment_status.replaceAll('_',' '))}</span></div>${b.refunded?`<div><span>Refunded</span><strong>${money(b.refunded)}</strong></div>`:''}</div><div class="modal-actions">${b.status==='held'?btn('Continue to Square deposit','deposit-pay','primary',`data-token="${e(raw)}"`)+btn('Check payment status','manage-refresh',''):''}${data.can_change?`${btn(icon('calendar')+' Reschedule','customer-reschedule-open')}${btn('Cancel booking','customer-cancel','danger')}`:''}${b.status==='confirmed'?`<a href="/api/public/manage/${e(raw)}/calendar.ics" class="btn">${icon('download')} Add to calendar</a>`:''}</div></div><div id="customer-photos" class="card card-pad mt24"></div><div class="card card-pad mt24"><h3>Questions or changes?</h3><p class="muted small mt8">${e(s.cancellation_policy)}</p><div class="row wrap mt16"><a class="btn small" href="mailto:${e(data.shop.correspondence_email||S.config.support_email)}">${icon('mail')} Contact the business</a>${s.phone?`<span class="muted small">${e(s.phone)}</span>`:''}</div></div><p class="muted small mt24">Keep this private booking link safe. Anyone with the link can view this booking and make eligible changes.</p></main>${businessFooter(data.shop)}</div>`;await customerPhotoPanel(raw);if(b.status==='held'){clearTimeout(S.pollTimer);S.pollTimer=setTimeout(async()=>{if(location.pathname==='/manage/'+raw)try{await renderManage(raw);}catch{}},7000);}}
async function renderDemoCheckout(raw){const data=await api('/public/manage/'+raw);$('#app').innerHTML=`<main id="main" class="booking-manage">${brand()}<div class="card card-pad mt32"><span class="pill amber">Simulation only</span><h1 class="mt24">Try the deposit flow.</h1><p class="muted mt16">This is a local demonstration, not Square checkout. No real card details are needed, and no money will move.</p><div class="price-large mt24">${money(data.booking.deposit)}</div><p class="muted small">Simulated booking deposit for ${e(data.shop.name)}.</p>${btn('Simulate a successful deposit '+icon('check'),'demo-pay','primary wide mt24',`data-token="${e(raw)}"`)}${nav('Back to booking','/manage/'+raw,'btn wide mt16')}</div></main>`;}
async function openPaddle(){if(!S.config.paddle_client_token){$('#checkout-status').innerHTML='<div class="notice amber">The platform operator must configure a Paddle client token before subscription checkout is available.</div>';return;}const tx=new URLSearchParams(location.search).get('_ptxn');if(!tx||!/^txn_[a-z0-9]+$/.test(tx)){throw new Error('This checkout link is invalid. Open a new checkout from Subscription.');}await new Promise((resolve,reject)=>{if(window.Paddle)return resolve();const script=document.createElement('script');script.src='https://cdn.paddle.com/paddle/v2/paddle.js';script.onload=resolve;script.onerror=()=>reject(new Error('Paddle checkout could not load. Please try again.'));document.head.appendChild(script);});if(S.config.paddle_environment==='sandbox')Paddle.Environment.set('sandbox');Paddle.Initialize({token:S.config.paddle_client_token,eventCallback:event=>{if(event.name==='checkout.completed'){toast('Payment submitted. Your subscription updates after provider verification.');go('/app/billing');}}});Paddle.Checkout.open({transactionId:tx,settings:{theme:'light',displayMode:'overlay',successUrl:location.origin+'/app/billing'}});}
async function refreshMe(){S.me=await api('/auth/me');}
async function persistSettings(settings){await api('/settings',{method:'PUT',body:settings});S.dirty=false;await refreshMe();toast('Saved. New bookings will use these settings.');}
function cents(value){const str=String(value).trim();if(!/^\d+(\.\d{1,2})?$/.test(str))throw new Error('Enter a positive amount with no more than two decimal places.');return Math.round(Number(str)*100);}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Link copied.');}catch{openModal('Your link',`<p class="muted small mb16">Copy this link to share it.</p><input readonly value="${e(text)}" aria-label="Link to copy">`);$('input',$('#modal')).select();}}
function serviceEditor(kind,index){const list=kind==='package'?'packages':kind==='extra'?'extras':'vehicles';const x=S.me.shop.settings[list][index]||{name:'',description:'',price:0,minutes:kind==='package'?90:0,active:true};openModal(`${index<0?'Add':'Edit'} ${kind}`,`<form data-form="service-edit" data-dirty data-kind="${kind}" data-index="${index}">${field('Name','name',x.name,'text','required minlength="2" maxlength="60"')}${kind==='package'?`<div class="field mt16"><label for="service-description">Description</label><textarea id="service-description" name="description" maxlength="300">${e(x.description)}</textarea></div>`:''}<div class="form-grid mt16">${field(kind==='vehicle'?'Default adjustment (USD)':kind==='package'?'Base price (USD)':'Price (USD)','price',(x.price/100).toFixed(2),'number',`required min="${kind==='package'?1:0}" step="0.01" max="10000"`)}${field('Duration / extra time (minutes)','minutes',x.minutes,'number',`required min="${kind==='package'?30:0}" max="${kind==='package'?600:kind==='vehicle'?180:240}"`)}</div>${kind==='package'?'<p class="muted small mt16">Base price applies with the vehicle default unless you set an individual price. Existing individual prices are kept.</p>':''}${kind!=='vehicle'?`<label class="check-row mt24"><input name="active" type="checkbox" ${x.active?'checked':''}><span>Visible to customers</span></label>`:''}<div class="form-footer"><button class="btn primary" type="submit">Save ${kind}</button></div></form>`);}
async function showBlocks(){const result=await api('/blocks');const n=$('#blocks-list');if(n)n.innerHTML=result.blocks.length?result.blocks.map(b=>`<div class="row between" style="padding:12px 0;border-bottom:1px solid var(--line)"><div><strong class="small">${e(b.label)}</strong><p class="muted small">${dateLabel(b.start_ts,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})} — ${dateLabel(b.end_ts,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}</p></div><button class="icon-btn" data-action="block-delete" data-id="${e(b.id)}" aria-label="Delete blocked time">${icon('trash')}</button></div>`).join(''):'<p class="muted small">No upcoming blocked time.</p>';}
async function rescheduleModal(kind,key){S.reschedule={kind,key};const zone=kind==='customer'?S.manage.shop.settings.timezone:S.me.shop.settings.timezone;const date=todayISO(zone);openModal('Find a new time',`<p class="muted small mb16">Times are in ${e(zone)}. Your deposit stays with the booking.</p><form data-form="reschedule"><div class="field"><label for="reschedule-date">New date</label><input id="reschedule-date" type="date" data-reschedule-date name="date" value="${date}" min="${date}" required></div><div id="reschedule-slots" class="mt16">${skeleton()}</div><div class="form-footer"><button class="btn primary" type="submit">Confirm new time</button></div></form>`);await loadRescheduleSlots(date);}
async function loadRescheduleSlots(date){const r=S.reschedule;const path=r.kind==='customer'?'/public/manage/'+r.key:'/bookings/'+r.key;try{const result=await api(path+'/slots?date='+date);if(!$('#reschedule-slots'))return;$('#reschedule-slots').innerHTML=result.slots.length?`<div class="slots">${result.slots.map(x=>`<label class="slot check-row"><input type="radio" name="start_ts" value="${x.start_ts}" required><span>${e(x.label)}</span></label>`).join('')}</div>`:'<div class="notice">No times fit on this day. Please choose another date.</div>';}catch(err){$('#reschedule-slots').innerHTML=`<div class="notice error">${e(err.message)}</div>`;}}
async function action(name,node){if(await workflowAction(name,node))return;if(await releaseAction(name,node))return;if(name==='brand-return'){go('/app/branding');return;}if(name.startsWith('brand-'))return brandingAction(name,node);const value=node.dataset.value,id=node.dataset.id;switch(name){case'quote-photo-delete':if(confirm('Delete this quote photo from active storage?')){toast((await api('/photos/'+node.dataset.id,{method:'DELETE'})).message);await renderPage();}break;case'photos-choose-job':await choosePhotoJob();break;case'photos-open':await openJobPhotos(node.dataset.id);break;case'photos-save':await saveJobPhotos();break;case'photos-filter':PhotoState.filter=value;$('#main').innerHTML=renderPhotoLibrary();break;case'photo-view':viewPhoto(node.dataset.id);break;case'photo-delete':await deleteJobPhoto(node.dataset.id);break;case'photos-customer-open':await openCustomerPhotos(node.dataset.token);break;case'modal-close':closeModal();break;case'menu':$('.shell')?.classList.toggle('menu-open');break;case'reload':await render();break;case'enter-demo':{const r=await api('/auth/demo',{method:'POST'});S.me={csrf:r.csrf};go('/app');break;}case'logout':await api('/auth/logout',{method:'POST'});S.me=null;go('/login');break;case'copy-booking-link':await copyText(S.me.shop.booking_url||location.origin+'/book/'+S.me.shop.slug);break;case'copy-customer-link':await copyText((await api('/bookings/'+id+'/link')).url);break;case'booking-open':bookingModal(id);break;case'booking-view':S.bookingView=value;$('#main').innerHTML=bookingsPage();break;case'week-back':S.week=addDays(S.week||todayISO(S.me.shop.settings.timezone),-7);$('#main').innerHTML=bookingsPage();break;case'week-next':S.week=addDays(S.week||todayISO(S.me.shop.settings.timezone),7);$('#main').innerHTML=bookingsPage();break;case'booking-action':if(value==='cancel'&&!confirm('Cancel this appointment? The time will be released. This does not refund a deposit.'))break;await api('/bookings/'+id+'/action',{method:'POST',body:{action:value}});closeModal();toast(value==='cancel'?'Booking cancelled. Refunds are separate.':'Booking updated.');await renderPage();break;case'refund-open':openModal('Refund the deposit?',`<p>This sends a refund request to the payment provider. It does not cancel the appointment.</p><p class="muted small mt16">Check your cancellation policy and customer agreement before proceeding. This action cannot be automatically undone.</p><div class="modal-actions">${btn('Keep deposit','modal-close')}${btn('Yes, refund the deposit','refund-confirm','danger',`data-id="${e(id)}"`)}</div>`);break;case'refund-confirm':{const r=await api('/bookings/'+id+'/refund',{method:'POST',body:{confirmation:'REFUND DEPOSIT'}});closeModal();toast(r.status==='refunded'?'Deposit refunded.':'Refund submitted. Awaiting provider confirmation.');await renderPage();break;}case'reschedule-open':await rescheduleModal('owner',id);break;case'quote-offer':{const q=S.quotes.find(x=>x.id===id);openModal('Prepare a custom quote',`<p class="muted small mb16">${e(q.customer_name)} · ${e(q.vehicle_notes||q.vehicle)}</p><form data-form="quote-offer" data-id="${e(id)}"><div class="form-grid">${field('Service subtotal (USD)','amount',q.amount?(q.amount/100).toFixed(2):'','number','required min="1" max="10000" step="0.01"')}${field('Service duration (minutes)','minutes',q.minutes||180,'number','required min="30" max="600"')}</div><div class="field mt16"><label for="quote-message">Message to your customer</label><textarea id="quote-message" name="message" required minlength="5" maxlength="1000">${e(q.message||'Thanks for the details. Here is your custom quote. Choose an available time using the link below.')}</textarea></div><p class="muted small mt16">The quote is valid for 7 days. Your configured tax and deposit rules are shown before the customer books.</p><div class="form-footer"><button class="btn primary" type="submit">Send quote ${icon('arrow')}</button></div></form>`);break;}case'quote-decline':if(!confirm('Decline this request and notify the customer?'))break;await api('/quotes/'+id+'/decline',{method:'POST'});toast('Customer notified.');await renderPage();break;case'package-edit':serviceEditor('package',Number(node.dataset.index));break;case'extra-edit':serviceEditor('extra',Number(node.dataset.index));break;case'vehicle-edit':serviceEditor('vehicle',Number(node.dataset.index));break;case'settings-tab':if(S.dirty&&!confirm('Discard your unsaved settings changes?'))break;S.dirty=false;S.settingsTab=value;$('#main').innerHTML=settingsPage();break;case'publish':await api('/publish',{method:'POST',body:{published:value==='true'}});await refreshMe();toast(value==='true'?'Your booking page is live.':'Your booking page is unpublished.');renderShell(location.pathname);await renderPage();break;case'resend-verification':toast((await api('/auth/resend-verification',{method:'POST'})).message);break;case'verify-email':toast((await api('/auth/verify-email',{method:'POST',body:{token:new URLSearchParams(location.search).get('token')||''}})).message);go('/app/settings');break;case'block-open':{const date=todayISO(S.me.shop.settings.timezone);openModal('Block time off',`<p class="muted small mb16">${e(S.me.shop.settings.timezone)}. Existing appointments must be rescheduled first.</p><form data-form="block">${field('Label','label','','text','required minlength="2" maxlength="80" placeholder="e.g. Personal appointment"')}<div class="form-grid mt16">${field('Start date','start_date',date,'date','required')}${field('Start time','start_time','09:00','time','required')}${field('End date','end_date',date,'date','required')}${field('End time','end_time','12:00','time','required')}</div><div class="form-footer"><button class="btn primary" type="submit">Block this time</button></div></form>`);break;}case'blocks-load':await showBlocks();break;case'block-delete':if(confirm('Remove this blocked time?')){await api('/blocks/'+id,{method:'DELETE'});await showBlocks();toast('Time is available again.');}break;case'square-connect':window.location.assign((await api('/integrations/square/connect',{method:'POST'})).url);break;case'square-disconnect':if(confirm('Disconnect Square and unpublish your booking page?')){toast((await api('/integrations/square/disconnect',{method:'POST'})).message);await refreshMe();await renderPage();}break;case'billing-checkout':window.location.assign((await api('/billing/checkout',{method:'POST'})).url);break;case'billing-portal':window.location.assign((await api('/billing/portal',{method:'POST'})).url);break;case'retry-emails':toast((await api('/operations/retry-emails',{method:'POST'})).message);await renderPage();break;case'delete-account-open':openModal('Permanently delete this account?',`<p class="notice error mb16">This removes your active application records. Export your data first. Upcoming bookings and active subscriptions must be resolved.</p><form data-form="delete-account">${field('Confirm your password','password','','password','required autocomplete="current-password"')}<div class="form-footer"><button class="btn danger" type="submit">Delete my account permanently</button></div></form>`);break;case'wizard-package':S.wizard.package_id=value;S.wizard.start_ts=null;S.wizard.submission=null;await priceWizard();renderWizard();break;case'wizard-vehicle':S.wizard.vehicle_id=value;S.wizard.start_ts=null;S.wizard.submission=null;await priceWizard();renderWizard();break;case'wizard-next':if(S.wizard.step===1){await priceWizard();if(S.wizard.zip.length!==5||S.wizard.priceError)throw new Error(S.wizard.priceError||'Enter a valid five-digit ZIP code.');if(S.wizard.condition==='heavy'){S.wizard.step=3;renderWizard();}else{if(!S.wizard.price)throw new Error('Choose a valid service first.');S.wizard.step=2;renderWizard();await loadSlots();}}else{if(!S.wizard.start_ts)throw new Error('Choose an appointment time.');S.wizard.step=3;renderWizard();}window.scrollTo({top:0,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});break;case'wizard-back':{const form=$('[data-form="wizard-details"]');if(form){const fd=new FormData(form);S.wizard.customer={...S.wizard.customer,...Object.fromEntries(fd.entries()),has_water:fd.has('has_water'),has_power:fd.has('has_power')};}if(S.wizard.submission)throw new Error('A reservation attempt already exists. Retry the same submission or contact the business before making a new booking.');S.wizard.step=S.wizard.condition==='heavy'?1:Math.max(1,S.wizard.step-1);renderWizard();if(S.wizard.step===2)await loadSlots();break;}case'wizard-date':S.wizard.date=value;S.wizard.start_ts=null;renderWizard();await loadSlots();break;case'wizard-slot':S.wizard.start_ts=Number(value);$('#slot-options').innerHTML=slotMarkup();$('#wizard-summary').innerHTML=wizardSummary();$('[data-action="wizard-next"]').disabled=false;break;case'demo-pay':{const result=await api('/demo-checkout/'+node.dataset.token,{method:'POST'});go(result.url);break;}case'manage-refresh':await renderManage(S.manage.token);break;case'customer-cancel':if(confirm('Cancel your appointment? Any deposit refund is reviewed separately by the business.')){toast((await api('/public/manage/'+S.manage.token+'/cancel',{method:'POST'})).message);await renderManage(S.manage.token);}break;case'customer-reschedule-open':await rescheduleModal('customer',S.manage.token);break;default:console.warn('Unknown action',name);}}
async function submit(form){if(await workflowSubmit(form))return;if(await releaseSubmit(form))return;if(['branding','booking-slug','brand-domain'].includes(form.dataset.form))return brandingSubmit(form);const fd=new FormData(form),data=Object.fromEntries(fd.entries()),type=form.dataset.form;switch(type){case'photo-edit':await editJobPhoto(form);break;case'login':{const result=await api('/auth/login',{method:'POST',body:data});S.me={csrf:result.csrf};go('/app');break;}case'register':{data.accepted_terms=fd.has('accepted_terms');const r=await api('/auth/register',{method:'POST',body:data});S.me={csrf:r.csrf};toast(r.message);go('/app/setup');break;}case'forgot':toast((await api('/auth/forgot-password',{method:'POST',body:data})).message);break;case'reset':toast((await api('/auth/reset-password',{method:'POST',body:{token:new URLSearchParams(location.search).get('token')||'',password:data.password}})).message);go('/login');break;case'settings-business':{const s=structuredClone(S.me.shop.settings);Object.assign(s,{name:data.name,city:data.city,tagline:data.tagline,phone:data.phone,contact_email:data.contact_email,timezone:data.timezone,zip_codes:data.zip_codes.split(/[\s,]+/).filter(Boolean),requires_water:fd.has('requires_water'),requires_power:fd.has('requires_power')});await persistSettings(s);await render();break;}case'settings-schedule':{const s=structuredClone(S.me.shop.settings);s.hours=s.hours.map((_,i)=>({enabled:fd.has('day-'+i),start:data['start-'+i],end:data['end-'+i]}));for(const key of ['buffer_minutes','lead_hours','horizon_days'])s[key]=Number(data[key]);await persistSettings(s);await renderPage();break;}case'settings-payments':{const s=structuredClone(S.me.shop.settings);s.deposit_percent=Number(data.deposit_percent);s.tax_basis_points=cents(data.tax_rate);await persistSettings(s);await renderPage();break;}case'settings-policy':{const s=structuredClone(S.me.shop.settings);s.cancellation_hours=Number(data.cancellation_hours);s.cancellation_policy=data.cancellation_policy;s.policy_reviewed=fd.has('policy_reviewed');await persistSettings(s);await renderPage();break;}case'service-edit':{const s=structuredClone(S.me.shop.settings),kind=form.dataset.kind,index=Number(form.dataset.index),key=kind==='package'?'packages':kind==='extra'?'extras':'vehicles';const item={id:index<0?'item-'+crypto.randomUUID().slice(0,8):s[key][index].id,name:data.name,price:cents(data.price),minutes:Number(data.minutes)};if(kind==='package'){item.description=data.description;item.vehicle_rates=index<0?{}:s[key][index].vehicle_rates||{};}if(kind!=='vehicle')item.active=fd.has('active');if(index<0)s[key].push(item);else s[key][index]=item;await persistSettings(s);closeModal();await renderPage();break;}case'quote-offer':{const result=await api('/quotes/'+form.dataset.id+'/offer',{method:'POST',body:{amount:cents(data.amount),minutes:Number(data.minutes),message:data.message}});closeModal();toast(result.message);await renderPage();break;}case'block':{const zone=S.me.shop.settings.timezone;await api('/blocks',{method:'POST',body:{label:data.label,start_ts:localTimestamp(data.start_date,data.start_time,zone),end_ts:localTimestamp(data.end_date,data.end_time,zone)}});closeModal();toast('Time blocked.');await showBlocks();break;}case'reschedule':{if(!data.start_ts)throw new Error('Select an available time.');const r=S.reschedule;await api((r.kind==='customer'?'/public/manage/'+r.key:'/bookings/'+r.key)+'/reschedule',{method:'POST',body:{start_ts:Number(data.start_ts)}});closeModal();toast('Appointment rescheduled.');if(r.kind==='customer')await renderManage(r.key);else await renderPage();break;}case'wizard-details':await submitWizard(form);break;case'change-password':{const r=await api('/auth/change-password',{method:'POST',body:data});S.me.csrf=r.csrf;toast(r.message);form.reset();break;}case'delete-account':if(!confirm('This is permanent. Delete this account and its active application records?'))break;toast((await api('/account',{method:'DELETE',body:{password:data.password,confirmation:'DELETE MY ACCOUNT'}})).message);closeModal();S.me=null;go('/');break;}}
document.addEventListener('click',async event=>{const link=event.target.closest('a[data-nav]');if(link){const href=link.getAttribute('href');if(href.startsWith('#')||href.startsWith('/api/')||/^https?:/.test(href)||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;event.preventDefault();go(href);return;}const node=event.target.closest('[data-action]');if(!node||node.disabled||node.dataset.running==='true')return;event.preventDefault();node.dataset.running='true';if(node.tagName==='BUTTON'){node.disabled=true;node.classList.add('busy');}try{await action(node.dataset.action,node);}catch(err){toast(err.message,true);}finally{node.dataset.running='false';if(node.tagName==='BUTTON'){node.disabled=false;node.classList.remove('busy');}}});
document.addEventListener('submit',async event=>{const form=event.target;if(!form.dataset.form)return;event.preventDefault();const buttons=$$('button[type="submit"]',form);buttons.forEach(b=>{b.disabled=true;b.classList.add('busy');});$('.form-error',form)?.remove();try{await submit(form);}catch(err){formError(form,err.message);}finally{buttons.forEach(b=>{b.disabled=false;b.classList.remove('busy');});}});
let zipTimer,searchTimer;
document.addEventListener('input',event=>{const n=event.target;if(n.closest('[data-dirty]'))S.dirty=true;if(n.dataset.wfield){S.wizard[n.dataset.wfield]=n.value;S.wizard.start_ts=null;clearTimeout(zipTimer);zipTimer=setTimeout(priceWizard,250);}if(n.dataset.search==='bookings'){S.search=n.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const cursor=n.selectionStart;$('#main').innerHTML=bookingsPage();const next=$('[data-search="bookings"]');next.focus();next.setSelectionRange(cursor,cursor);},180);}if(n.name==='business'&&n.closest('[data-form="register"]')){const slug=$('[name="slug"]');if(!slug.dataset.touched)slug.value=n.value.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,45);}if(n.name==='slug')n.dataset.touched='true';});
document.addEventListener('change',async event=>{const n=event.target;try{if(n.dataset.wextra){const w=S.wizard;w.extra_ids=n.checked?[...w.extra_ids,n.dataset.wextra]:w.extra_ids.filter(x=>x!==n.dataset.wextra);w.start_ts=null;await priceWizard();}if(n.hasAttribute('data-wcondition')){S.wizard.condition=n.checked?'heavy':'standard';await priceWizard();renderWizard();}if(n.hasAttribute('data-wdate')){S.wizard.date=n.value;S.wizard.start_ts=null;renderWizard();await loadSlots();}if(n.hasAttribute('data-reschedule-date'))await loadRescheduleSlots(n.value);if(n.dataset.filter==='bookings'){S.bookingFilter=n.value;$('#main').innerHTML=bookingsPage();}}catch(err){toast(err.message,true);}});
document.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target.matches('tr[data-action]')){event.preventDefault();event.target.click();}});
window.addEventListener('beforeunload',event=>{if(S.dirty||BrandState.busy){event.preventDefault();event.returnValue='';}});
window.addEventListener('popstate',()=>{S.dirty=false;closeModal();render();});
$('#modal').addEventListener('cancel',event=>{event.preventDefault();closeModal();});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
render();
